import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero,compileTechnique} from '../mako.js';import {applySupply,ITEMS} from '../repertoire.js?v=5.6.0';
import {combatContext,REACTION_RULES} from '../combat-reactions.js';import {COMBAT_RELICS,relicObjects,collectCombatRelic,equipCombatRelic,unequipCombatRelic} from '../combat-relics.js';import {physicalBindings,physicalState} from '../physical-lore.js';import {World} from '../world.js';
function setup(tags=[]){const heroes=[0,1,2].map(id=>defaultHero(id,10)),enemies=[0,1,2].map(i=>makeEnemy('predator',10,i));heroes.forEach((h,i)=>{h.x=i;h.y=0;});enemies.forEach((e,i)=>{e.x=3+i;e.y=0;e.hp=e.maxHp=10000;});const b=new Battle({heroes,enemies,context:{version:1,tags,walkable:Array.from({length:5},(_,y)=>Array.from({length:12},(_,x)=>[x-2,y-2])).flat()}});heroes[0].atb=1;return b;}
function hit(b,core,status={},physical=false){const h=b.heroes[0],e=b.enemies[0];Object.assign(e.status,status);return b.damage(h,e,100,{core,physical});}
test('conduction consumes water, increases impact and only equipped Stormcoil adds one bounded arc',()=>{const a=setup(),base=hit(a,'volt').damage,b=setup();b.heroes[0].battleRelics=['stormcoil'];const side=b.enemies[1].hp,out=hit(b,'volt',{wet:5});assert.equal(out.damage,base*1.6);assert.equal(b.enemies[0].status.wet,undefined);assert.ok(b.enemies[1].hp<side);assert.equal(b.events.filter(e=>e.type==='reaction-arc').length,1);const neutral=setup();hit(neutral,'volt',{wet:5});assert.equal(neutral.events.filter(e=>e.type==='reaction-arc').length,0);});
test('freeze creates one brittle opening; follow-up physical strike consumes it and breaks armor',()=>{const b=setup(),e=b.enemies[0];e.armor=80;hit(b,'frost',{wet:5});assert.ok(e.status.brittle);b.heroes[0].battleRelics=['frostline'];const armor=e.armor,first=hit(b,'physical',{},true);assert.ok(e.armor<armor);assert.equal(e.status.brittle,undefined);const second=hit(b,'physical',{},true);assert.ok(first.damage>second.damage);});
test('steam consumes setup, extinguishes burn and Riverglass supplies a capped defensive payoff',()=>{const b=setup(),h=b.heroes[0];h.battleRelics=['riverglass'];const out=hit(b,'tide',{burn:5});assert.equal(out.damage,80);assert.equal(b.enemies[0].status.burn,undefined);assert.equal(h.status.shield,25);b.enemies[0].status.wet=5;h.atb=1;const inv={emberBomb:1};assert.ok(applySupply(b,inv,'emberBomb',h,b.enemies[0]));assert.equal(b.enemies[0].status.burn,undefined);});
test('vitrification reduces fire then Earth shatters the stored defense',()=>{const b=setup(),e=b.enemies[0];hit(b,'flame',{shield:150});assert.ok(e.status.glazed);const shield=e.status.shield;b.heroes[0].battleRelics=['kilnglaze'];const out=hit(b,'earth');assert.equal(e.status.glazed,undefined);assert.ok(e.status.shield<shield);assert.ok(out.amount>100);});
test('ground fault, crosswind, witness echo and gravity affect actual charge, statuses and positions',()=>{let b=setup(),e=b.enemies[0];e.intent={left:2};e.armor=80;hit(b,'earth',{shock:4});assert.equal(e.intent,null);assert.ok(e.armor<80);b=setup();hit(b,'gale',{burn:5});assert.ok(b.enemies[1].status.burn);b=setup();b.heroes[0].battleRelics=['witnessopal'];hit(b,'shade',{exposed:5});assert.equal(b.events.filter(e=>e.type==='reaction-arc').length,1);b=setup();const x=b.enemies[1].x;hit(b,'gravity',{wet:5});assert.ok(b.enemies[1].x<x);});
test('overhealing, Echo and Link relics are conditional and bounded',()=>{let b=setup(['living']),h=b.heroes[0];h.battleRelics=['graftroot'];b.apply(h,h,compileTechnique('mend','focus'));assert.ok(h.status.shield>0&&h.status.shield<=80);b=setup(['resonant']);h=b.heroes[0];h.battleRelics=['bellrest'];h.status.guard=5;h.mp=100;b.command(h.id,'tech',b.enemies[0].id,compileTechnique('gale','echo'));assert.equal(b.delayed[0].multiplier,.85);assert.equal(b.delayed[0].at,1.4);assert.equal(h.status.guard,undefined);b=setup();h=b.heroes[0];h.battleRelics=['dawnspindle'];h.mp=100;b.heroes[1].atb=1;b.heroes[1].status.shield=60;b.command(h.id,'tech',b.enemies[0].id,compileTechnique('gale','link'));assert.equal(b.heroes[1].status.shield,40);assert.ok(h.status.guard);});
test('battle replay retains terrain, cooldowns, equipped relics and delayed action strength',()=>{const b=setup(['wet','resonant']);b.heroes[0].battleRelics=['stormcoil'];hit(b,'volt');const saved=b.snapshot(),copy=setup();copy.restore(saved);assert.deepEqual(copy.context,b.context);assert.deepEqual(copy.reactionCooldowns,b.reactionCooldowns);assert.deepEqual(copy.heroes[0].battleRelics,['stormcoil']);});
test('all 45 item effects emit a source-specific visual on a successful use',()=>{for(const item of ITEMS){const b=setup(['heat']),h=b.heroes[0];for(const ally of b.heroes){ally.hp*=.4;ally.mp=0;ally.strain=80;ally.status.burn=5;}b.heroes[2].hp=0;for(const e of b.enemies){e.status.guard=3;e.armor=70;e.atb=.8;e.intent={left:1,total:2};}const inv={[item.id]:1};assert.ok(applySupply(b,inv,item.id,h,b.enemies[0]),item.id);const event=b.events.find(e=>e.type==='supply');assert.equal(event.item.id,item.id);assert.ok(event.targets.length&&event.visual,item.id);assert.equal(b.pendingSupply,undefined);}});
test('each rare collectible is earned at a real site, claimed once and unique across wearers and saves',()=>{const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),w=new World(data);w.state.chapter=24;w.state.story.firstCore=true;w.state.recruited=[0,1];physicalState(w.state).claimed=COMBAT_RELICS.map(r=>r.source);for(const r of COMBAT_RELICS){const site=physicalBindings(w).find(o=>o.physicalId===r.source&&o.physicalRole==='reward');w.state.scene=site.physicalLocation;w.state.x=site.xy[0]+.5;w.state.y=site.xy[1]+.5;w.state.mode='field';const o=relicObjects(w).find(o=>o.battleRelic===r.id);assert.ok(o,r.id);w.interact(o);w.interact(o);assert.equal(w.state.combatRelics.owned.filter(id=>id===r.id).length,1);}assert.ok(equipCombatRelic(w.state,0,'stormcoil',0));assert.equal(equipCombatRelic(w.state,1,'stormcoil',0),false);w.state.mode='battle';assert.equal(unequipCombatRelic(w.state,0,0),false);w.state.mode='field';const saved=w.save();w.restore(saved);assert.equal(w.state.heroes[0].battleRelics[0],'stormcoil');assert.equal(w.state.combatRelics.owned.length,8);});
test('scene context derives distinct terrain rules without requiring rare collectibles',()=>{const state={chapter:3,physicalLore:{completed:[]}},world={state,data:{},scene:{key:'river',location:49,chapter:3}};assert.ok(combatContext(world).tags.includes('wet'));world.scene.key='reactor';assert.ok(combatContext(world).tags.includes('heat'));assert.equal(REACTION_RULES.length,13);});
test('action order is noncommutative and secondary arcs cannot recursively propagate',()=>{const a=setup(),b=setup();a.enemies[0].status.wet=5;b.enemies[0].status.wet=5;const first=hit(a,'frost').damage+hit(a,'physical',{},true).damage,second=hit(b,'physical',{},true).damage+hit(b,'frost').damage;assert.ok(first>second);const c=setup();c.heroes[0].battleRelics=['stormcoil','witnessopal'];c.enemies.forEach(e=>e.status.wet=5);hit(c,'volt');assert.equal(c.events.filter(e=>e.type==='reaction-arc').length,1);assert.ok(c.enemies[1].status.wet);assert.equal(c.enemies[2].hp,c.enemies[2].maxHp);});
test('local restoration and regional preparation contribute bounded optional battle conditions',()=>{const world={state:{chapter:6,physicalLore:{completed:['grounding-spool']},regionalLife:{projects:[6]}},data:{},scene:{chapter:6,key:'catwalk',location:28}},context=combatContext(world);assert.ok(context.tags.includes('grounded'));assert.ok(context.tags.includes('prepared'));const b=setup(context.tags);assert.equal(b.heroes[0].status.shield,15);assert.equal(hit(b,'volt').amount,85);});
test('restorative supplies participate in Graftroot protection and cures remove new harmful conditions',()=>{const b=setup(),h=b.heroes[0];h.battleRelics=['graftroot'];h.hp=h.maxHp-10;h.atb=1;assert.ok(applySupply(b,{tonic:1},'tonic',h,b.enemies[0]));assert.ok(h.status.shield>0&&h.status.shield<=80);h.atb=1;h.status.brittle=6;assert.ok(applySupply(b,{clearSalt:1},'clearSalt',h,b.enemies[0]));assert.equal(h.status.brittle,undefined);});
